package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ReferenceType_getGenericSignature_TriageGen2Test {

    @Test
    public void testGetGenericSignature_Success() {
        // Arrange
        Class<?> clazz = String.class;
        JavaType mockReferencedType = mock(JavaType.class);

        // We need to use the static factory method to create the instance
        // since the constructor is protected.
        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType, null, null);

        StringBuilder sb = new StringBuilder("prefix");

        // Mock the behavior of the referenced type's getGenericSignature
        // The method signature is: sb = _referencedType.getGenericSignature(sb);
        // We simulate it appending "TypeContent" to the builder
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder passedSb = invocation.getArgument(0);
            passedSb.append("TypeContent");
            return passedSb;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Expected flow: 
        // 1. _classSignature (appends class name, e.g., "java.lang.String")
        // 2. append('<')
        // 3. _referencedType.getGenericSignature (appends "TypeContent")
        // 4. append(';')
        // Note: _classSignature implementation details depend on internal Jackson logic, 
        // but for a standard class it appends the name.

        String expectedPrefix = clazz.getName(); 
        String expectedFull = expectedPrefix + "<TypeContent;";

        assertEquals(expectedFull, result.toString());

        // Verify interactions
        verify(mockReferencedType).getGenericSignature(any(StringBuilder.class));
    }

    @Test
    public void testGetGenericSignature_EmptyStringBuilder() {
        // Arrange
        Class<?> clazz = Integer.class;
        JavaType mockReferencedType = mock(JavaType.class);
        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType, null, null);

        StringBuilder sb = new StringBuilder();

        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder passedSb = invocation.getArgument(0);
            passedSb.append("Int");
            return passedSb;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        String expected = Integer.class.getName() + "<Int;";
        assertEquals(expected, result.toString());
    }

    @Test
    public void testGetGenericSignature_ReferencedTypeReturnsDifferentBuilder() {
        // Arrange
        Class<?> clazz = Object.class;
        JavaType mockReferencedType = mock(JavaType.class);
        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType, null, null);

        StringBuilder sb = new StringBuilder("start");
        StringBuilder newSb = new StringBuilder("new_sb");

        // Simulate the case where the referenced type returns a completely different StringBuilder instance
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenReturn(newSb);

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // The logic is: sb = _referencedType.getGenericSignature(sb);
        // So the result is the one returned by the referenced type + ';'
        // The class signature part was appended to the original 'sb'
        // Original sb becomes: "start" + "java.lang.Object" + "<"
        // But the method reassigns 'sb' to the return value of the mock.

        // Let's trace exactly:
        // 1. _classSignature(Object.class, sb, false) -> sb is "startjava.lang.Object"
        // 2. sb.append('<') -> sb is "startjava.lang.Object<"
        // 3. sb = mock.getGenericSignature(sb) -> sb is now "new_sb"
        // 4. sb.append(';') -> sb is "new_sb;"

        assertEquals("new_sb;", result.toString());
    }
}
